#include <stdio.h>

int gcd(int a, int b) {
    while (b) {
        int t = b;
        b = a % b;
        a = t;
    }
    return a;
}

int main() {
    int N;
    scanf("%d", &N);
    int A[N];
    for (int i = 0; i < N; i++) {
        scanf("%d", &A[i]);
    }

    int g = A[0];
    for (int i = 1; i < N; i++) {
        g = gcd(g, A[i]);
    }

    // Divide all numbers by initial GCD (though given as 1, but just in case)
    int odd_count = 0;
    for (int i = 0; i < N; i++) {
        A[i] /= g;
        if (A[i] % 2 == 1) odd_count++;
    }

    // If all numbers are 1 already, first player loses
    int all_one = 1;
    for (int i = 0; i < N; i++) {
        if (A[i] != 1) {
            all_one = 0;
            break;
        }
    }
    if (all_one) {
        printf("Second\n");
        return 0;
    }

    // Count number of even numbers
    int even_count = N - odd_count;

    if (even_count % 2 == 1) {
        printf("First\n");
    } else {
        printf("Second\n");
    }

    return 0;
