    ll g = 0;
    ll mx = 0;
    for (int i = 0; i < N; i++) {
        ll x;
        scanf("%lld", &x);
        g = gcdll(g, x);
        if (x > mx) mx = x;
    }

    /* Given gcd of all numbers is 1.
       This game is equivalent to Nim with total move count determined by max(A)-N.
       Winner:
       - if (max - N) is odd -> first player
       - else -> second player
    */
    if ((mx - N) % 2 != 0) {
        puts("First");
    } else {
        puts("Second");
    }

    return 0;
