using namespace std;

using int64 = long long;

// Euclidean algorithm step count for (a, b), assuming a >= b >= 1.
// Returns the number of modulo-steps until one becomes 0.
long long euclid_steps(long long a, long long b) {
    long long cnt = 0;
    while (b != 0) {
        long long r = a % b;
        a = b;
        b = r;
        cnt++;
    }
    return cnt;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<long long> A(N);
    for (int i = 0; i < N; i++) cin >> A[i];

    long long mn = *min_element(A.begin(), A.end());
    int cnt_min = 0;
    for (auto x : A) if (x == mn) cnt_min++;

    // Key fact:
    // The game value depends only on:
    // - the minimum value mn
    // - how many times it appears
    //
    // If mn appears at least twice, then every move must decrease one of the minima,
    // after which dividing by gcd normalizes exactly like subtracting 1 from mn.
    // The number of moves is mn - 1.
    //
    // If mn is unique, after reducing that minimum down to 1 and normalizing,
    // the game transforms according to one Euclidean step:
    //   (mn, next values) -> divide by gcd of differences with mn
    // Repeating this matches the Euclidean algorithm on the pair
    //   (mn, gcd of all A_i - mn).
    //
    // More directly, let g = gcd(A_i - mn) over all i.
    // Then the total number of moves equals the number of subtraction phases,
    // which is exactly the number of steps in Euclid(mn, g), but since g divides mn? not always.
    // The standard reduced form is equivalent to Euclid(max(mn, g), min(mn, g)).
    //
    // In fact here gcd(all A_i)=1, so final parity is:
    //   if cnt_min >= 2: parity of (mn - 1)
    //   else: parity of Euclid steps on (mn, gcd(A_i - mn))
    //
    // This is the known solution for this game.

    bool takahashiWins;

    if (cnt_min >= 2) {
        takahashiWins = ((mn - 1) % 2 == 1);
    } else {
        long long g = 0;
        for (auto x : A) {
            if (x != mn) g = std::gcd(g, x - mn);
        }
        long long a = max(mn, g), b = min(mn, g);
        long long steps = euclid_steps(a, b);
        takahashiWins = (steps % 2 == 1);
    }

    cout << (takahashiWins ? "Takahashi" : "Aoki") << '\n';
    return 0;
}

