import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static long gcd(long a, long b) {
        while (b != 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();
        long[] A = new long[N];
        long sum = 0;
        long g = 0;
        for (int i = 0; i < N; i++) {
            A[i] = fs.nextLong();
            sum += A[i];
            g = gcd(g, A[i]);
        }

        // Given gcd is 1, but keeping this for completeness.
        for (int i = 0; i < N; i++) A[i] /= g;

        // Key invariant:
        // Each move decreases the total sum by exactly 1 after normalization by gcd,
        // and the game ends exactly when all numbers are 1.
        // Therefore the number of moves is fixed: sum(A) - N.
        // First player wins iff this is odd.
        long moves = 0;
        for (int i = 0; i < N; i++) moves += A[i] - 1;

        System.out.println((moves % 2 == 1) ? "Takahashi" : "Aoki");
    }
}
